    /**
     * Checks whether the given string is already strictly valid (RFC compliant) JSON. Valid JSON includes
     * objects, arrays, strings, booleans, {@code null} and plain numbers.
     */
    private boolean isStrictlyValidJson(String jsonString) {
        try {
            STRICT_JSON_VALIDATOR.readValue(jsonString, Object.class);
            return true;
        } catch (IOException e) {
            return false;
        }
    }

    /**
     * Wraps a raw byte payload into a {@link BodyInserter} that transmits the bytes as-is. The Content-Type
     * header is set before the body is written so that it precedes any custom headers that get added while
     * the body is being serialized. When {@code contentType} is {@code null}, the Content-Type header is left
     * untouched so that any existing value (e.g. one configured by the user) is retained.
     */
    private BodyInserter<?, ?> wrapBodyWithContentType(byte[] bytes, MediaType contentType) {
        return (BodyInserter<Object, ClientHttpRequest>) (outputMessage, context) -> {
            if (contentType != null && outputMessage.getHeaders().getContentType() == null) {
                outputMessage.getHeaders().setContentType(contentType);
            }
            return outputMessage.writeWith(Mono.just(outputMessage.bufferFactory().wrap(bytes)));
        };
    }

    private static MediaType parseMediaTypeOrNull(String contentType) {
        if (!StringUtils.hasText(contentType)) {
            return null;
        }
        try {
            return MediaType.valueOf(contentType);
        } catch (Exception e) {
            return null;
        }
